import { useEffect } from 'react';

/**
 * useDismissable — composable hook for ad-hoc dismissable surfaces.
 *
 * For Dialog/Modal: use the <Dialog> primitive instead — it handles
 * outside-click + Escape internally.
 *
 * Use this hook only for tooltips, popovers, menus, or other transient
 * surfaces that don't warrant a full Dialog.
 *
 * Usage:
 *
 *   const ref = useRef(null);
 *   useDismissable(ref, () => setOpen(false), { disabled: !open });
 *   return <div ref={ref}>...</div>;
 *
 * Replaces the legacy useOutsideClick hook (which lacked Escape handling).
 *
 * Reference: .pitch/wcag-accessibility-audit/react-canonical-pattern.md (PR 1).
 */
export function useDismissable(ref, onDismiss, { disabled = false } = {}) {
    useEffect(() => {
        if (disabled || !onDismiss) return undefined;

        const handlePointer = (event) => {
            if (ref.current && !ref.current.contains(event.target)) {
                onDismiss(event);
            }
        };

        const handleKey = (event) => {
            if (event.key === 'Escape') {
                onDismiss(event);
            }
        };

        document.addEventListener('mousedown', handlePointer);
        document.addEventListener('keydown', handleKey);

        return () => {
            document.removeEventListener('mousedown', handlePointer);
            document.removeEventListener('keydown', handleKey);
        };
    }, [ref, onDismiss, disabled]);
}
