import SbUtils from '../../Utils/SbUtils'

const Template = ( props ) => {

    // a11y (SMASH-1377 v2 fix): the tile is the primary interactive control
    // for picking a template. Previously a <div onClick> — non-focusable,
    // unannounced as a control, and not activatable by Enter/Space. Promote
    // to a real <button> and strip native chrome with `sb-button-reset` so
    // the existing tile visuals (.sb-template-item) are preserved unchanged.
    return (
        <button
            type='button'
            className={ 'sb-template-item sb-button-reset' + (props?.customClass ? ' '+props?.customClass : '') }
            data-checked={props.isChecked}
            data-ispro={props.isTemplatePro}
            aria-pressed={ props.isChecked ? 'true' : 'false' }
            onClick={ () => {
                if( props?.onClick )
                    props.onClick()
            }}
        >
            <div className='sb-template-icon sb-fs'>
                { SbUtils.printIcon( props.type + '-template', 'sb-template-svg' ) }
            </div>
            <div className='sb-template-name sb-bold sb-text-small'>
                { props.title }
                {
                    props.isTemplatePro &&
                    SbUtils.printIcon( 'rocket', 'sb-template-name-svg', false, 12 )
                }
            </div>
        </button>
    )
}

export default Template;
